def is_not_prime(n):
    """Return True if n is a prime number, False otherwise."""
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_primes(n):
    """Return a set of all prime numbers less than n."""
    primes = set()
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            primes.add(i)
    return primes

def is_prime(n):
    """Return True if n is a prime number, False otherwise."""
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def heap_queue_largest(numbers):
    """Return the n largest integers from a list of numbers, sorted in descending order.

    Args:
        numbers: A list of integers.

    Returns:
        A list of integers in descending order.
    """
    if not numbers:
        return []
    heap = []
    for num in numbers:
        heap.append(num)
    return sorted(heap, reverse=True)

