def find_nth_number(sequence, n):
    """
    Find the nth number in the newman conway sequence.

    Args:
        sequence: A list of integers (can be of any length).
        n: The position in the sequence (1-based index).

    Returns:
        The nth number in the newman conway sequence.

    Raises:
        ValueError: If n is less than or equal to 0.
    """
    if n <= 0:
        raise ValueError("n must be a positive integer")
    if n == 1:
        return sequence[0]
    elif n == 2:
        return sequence[1]
    elif n == 3:
        return sequence[2]
    elif n == 4:
        return sequence[3]
    elif n == 5:
        return sequence[4]
    elif n == 6:
        return sequence[5]
    else:
        raise ValueError("n must be a positive integer")

def merge_dictionaries_three(d1, d2, d3):
    """Merge two dictionaries into a single dictionary.

    Args:
        d1: A dictionary containing keys 'R', 'B', 'P', 'G', 'W', 'O'.
        d2: A dictionary containing keys 'G', 'W', 'P', 'O'.
        d3: A dictionary containing keys 'P', 'G', 'W', 'O'.

    Returns:
        A new dictionary with all keys from both input dictionaries merged.
    """
    merged = {}
    for key in d1:
        if key in d2:
            merged[key] = d2[key]
        elif key in d3:
            merged[key] = d3[key]
    return merged

