def next_smallest_palindrome(n):
    """Return the smallest palindrome of a given integer.

    Args:
        n: An integer (can be negative, zero, or positive).

    Returns:
        An integer representing the next smallest palindrome.

    Raises:
        ValueError: If n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n % 2 == 0:
        return n + next_smallest_palindrome(n // 2)
    else:
        return n + next_smallest_palindrome(n // 2)

def eulerian_num(a, b):
    """
    Return the Eulerian number a(n, m) that is the sum of the first n
    positive integers that are divisible by b.

    Args:
        a (int): First positive integer.
        b (int): Second positive integer.

    Returns:
        int: The sum of the first n positive integers that are divisible by b.

    Raises:
        ValueError: If a or b is not positive integers.
    """
    if not isinstance(a, int) or not isinstance(b, int):
        raise ValueError("a and b must be integers")
    if a <= 0 or b <= 0:
        raise ValueError("a and b must be positive integers")
    if a > b:
        raise ValueError("a must be less than or equal to b")
    if b > a:
        raise ValueError("b must be greater than a")
    if a % b == 0:
        return a
    return sum(1 for num in range(a, b + 1))

