def sum_of_common_divisors(n1, n2):
    """
    Return the sum of all positive divisors of n1 and n2.

    Args:
        n1 (int): First number.
        n2 (int): Second number.

    Returns:
        int: The sum of all positive divisors of n1 and n2.
    """
    if n1 <= 1:
        return 0
    if n2 <= 1:
        return 1
    if n1 % n2 == 0:
        return n1
    divisors = [n1]
    for i in range(1, n2 + 1):
        if n1 % i == 0 and n2 % i == 0:
            divisors.append(i)
    return sum(divisors)

