def tuple_intersection(irrespective: List[Tuple[int, int]]) -> Tuple[int, int]:
    """
    Find the tuple intersection of elements in the given list irrespective of their order.

    Args:
        irrespective: A list of tuples, each containing integers and floats.

    Returns:
        A tuple (i, j) where i is the index of the first element in irrespective
        and j is the index of the second element in irrespective.
    """
    if not irrespective:
        return ()
    i, j = 0, 0
    for item in irrespective:
        if item[0] < item[1]:
            i = item[0]
        elif item[0] > item[1]:
            j = item[1]
    return (i, j)

