def Find_Max_Length(list):
    """Return the length of the longest sublists of a list of integers.

    Args:
        list: A list of integers.

    Returns:
        An integer representing the length of the longest sublists.
    """
    if not list:
        return 0
    max_len = 0
    current_len = 1
    for i in range(1, len(list)):
        if list[i] > list[i - 1]:
            current_len += 1
        else:
            current_len = 1
        if current_len > max_len:
            max_len = current_len
    return max_len

