def big_diff(nums):
    """Return the difference between the largest and smallest elements in `nums`.

    Args:
        nums: A list of integers.

    Returns:
        An integer representing the difference between the largest and smallest
        elements in `nums`.

    Raises:
        AssertionError: If `nums` is empty.
    """
    if not nums:
        raise AssertionError("Input list cannot be empty")
    largest = nums[0]
    smallest = nums[0]
    for num in nums[1:]:
        if num > largest:
            largest = num
        elif num < smallest:
            smallest = num
    return largest - smallest
