    """Return the n-th power of a list of integers.

    Args:
        n: A non-negative integer.
        power: A non-negative integer.

    Returns:
        The n-th power of the list.

    Raises:
        ValueError: If n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if power < 0:
        raise ValueError("power must be non-negative")
    if power == 0:
        return 1
    if power == 1:
        return 1
    return power * nth_power(n - 1, power - 1)

