def pair_wise(items):
    """Return a list of all pairs of consecutive items in `items`.

    Args:
        items: A list of integers.

    Returns:
        A list of tuples, each (i, j) where i < j.
    """
    pairs = []
    for i, item in enumerate(items):
        for j, value in enumerate(item):
            if i < j:
                pairs.append((i, j))
    return pairs

def sum_of_fourth_power_of_first_n(n: int) -> int:
    """
    Return the sum of fourth power of first n odd natural numbers.

    The function uses a recursive approach to compute the sum of the
    first n odd numbers. It handles edge cases such as n=0, n=1, and
    n=2.

    Args:
        n (int): The number of odd numbers to compute.

    Returns:
        int: The sum of the fourth power of first n odd numbers.

    Raises:
        ValueError: If n is not a positive integer.
    """
    if not isinstance(n, int) or n <= 0:
        raise ValueError("n must be a positive integer")

    def helper(n: int) -> int:
        """Recursive helper function."""
        if n == 0:
            return 0
        if n % 2 == 0:
            return helper(n // 2) + helper(n // 2)
        else:
            return helper(n // 2) + helper(n // 2)

    return helper(n)
