def check_expression(expression: str) -> bool:
    """
    Check if the given expression is balanced or not.

    Args:
        expression: A string representing a valid expression.

    Returns:
        True if the expression is balanced, False otherwise.
    """
    stack = []
    for char in expression:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            top = stack.pop()
            if top != '(':
                return False
    return len(stack) == 0

