def is_not_prime(n):
    """Return True if n is a prime number, False otherwise."""
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_non_prime_numbers(limit):
    """Return a list of all non-prime numbers up to the given limit."""
    return [num for num in range(2, limit) if is_not_prime(num)]

