def eulerian_num(n: int, m: int) -> int:
    """
    Find the Eulerian number a(n, m).

    Args:
        n: Number of terms.
        m: Number of terms.

    Returns:
        Eulerian number a(n, m).
    """
    if n == 0 or m == 0:
        return 1
    if n == 1:
        return 1
    if m == 1:
        return 1
    if n % 2 == 0:
        return eulerian_num(n // 2, m) + eulerian_num(n // 3, m)
    else:
        return eulerian_num(n // 3, m) + eulerian_num(n // 5, m)

