        list2: List of integers.

    Returns:
        Integer count of same pairs.
    """
    if len(list1) != len(list2):
        return 0
    for i in range(len(list1)):
        for j in range(i + 1, len(list1)):
            if list1[i] == list2[j]:
                return 1 + count_samepair(list1, list2)
    return 0

def max_diff(A, B):
    """Return the maximum difference between any two elements in A and B.

    Args:
        A: List of integers.
        B: List of integers.

    Returns:
        int: The maximum difference between any two elements.
    """
    if not A or not B:
        return 0
    if len(A) != len(B):
        return 0
    max_diff = 0
    for i in range(len(A)):
        for j in range(i + 1, len(A)):
            diff = A[i] - B[j]
            if diff > max_diff:
                max_diff = diff
    return max_diff

