    Args:
        s: The input string to analyze.

    Returns:
        The number of substrings that are non-empty.
    """
    n = len(s)
    if n <= 1:
        return 0

    # Precompute all possible substrings of length 1 to n
    substrings = []
    for i in range(1, n):
        for j in range(i):
            if s[i - 1] == s[j - 1]:
                substrings.append((i, j))

    # Count substrings of length 1 to n
    count = 0
    for i in range(1, n):
        for j in range(i):
            if s[i - 1] == s[j - 1]:
                count += 1

    return count

