from typing import List

def rear_extract(
    list_of_tuples: List[Tuple[int, str]],
    rear: int,
    front: int,
    max_size: int = 1000000
) -> List[int]:
    """Return the rear element of each tuple in the list.

    assert rear_extract([(1, 'Rash', 21), (2, 'Varsha', 20), (3, 'Kil', 19)]) == [21, 20, 19]
    """
    if rear < 0 or rear >= max_size:
        raise ValueError("rear must be between 0 and max_size")
    if front < 0 or front >= max_size:
        raise ValueError("front must be between 0 and max_size")
    if rear == 0:
        return list_of_tuples[rear]
    if rear == max_size - 1:
        return list_of_tuples[rear + 1]
    return list_of_tuples[rear] + list_of_tuples[rear - 1]

def even_binomial_Coeff_Sum(n):
    """Return the sum of even index binomial coefficients of n.

    Args:
        n: A non-negative integer.

    Returns:
        The sum of even index binomial coefficients of n.

    Raises:
        ValueError: If n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n % 2 == 0:
        return even_binomial_Coeff_Sum(n // 2) + even_binomial_Coeff_Sum(n // 2 + 1)
    else:
        return even_binomial_Coeff_Sum(n) + even_binomial_Coeff_Sum(n // 2) + even_binomial_Coeff_Sum(n // 2 + 1)

