def sum_of_product(n):
    """Return the sum of the product of consecutive binomial co-evaluations.

    Args:
        n: An integer.

    Returns:
        The sum of the product of consecutive binomial co-evaluations.

    Raises:
        ValueError: If n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1
    if n == 1:
        return 1
    if n == 2:
        return 1 * 1
    if n % 2 == 0:
        return n * n
    return n * (n - 1) // 2

def is_armstrong_number(number: int) -> bool:
    """Check if the given number is an Armstrong number.

    An Armstrong number is a number that is equal to the sum of its own
    digits each raised to the power of the number of digits.

    Args:
        number: An integer to check.

    Returns:
        True if the number is an Armstrong number, False otherwise.

    Examples:
        >>> is_armstrong_number(153)
        True
        >>> is_armstrong_number(1234)
        False
        >>> is_armstrong_number(123)
        True
    """
    if number < 0:
        return False
    # Count the number of digits
    digit_count = sum(int(digit) for digit in str(number))
    # Check if the sum of digits is equal to the number itself
    return digit_count == number
