    """
    Count the occurrences of each list in a list.

    Args:
        lists: A list of lists, each inner list is a list of integers.

    Returns:
        A dictionary mapping each list to its count.
        The key is the list's index (0-based), and the value is the number
        of times that list appears in the original list.

    Raises:
        TypeError: If the input is not a list.
    """
    if not isinstance(lists, list):
        raise TypeError("Input must be a list")

    result = {}
    for list in lists:
