def max_sum_increasing_subseq(nums, k):
    """
    Find the maximum sum of increasing subsequence from prefix until ith index and also including a given k.

    Args:
        nums: List of integers.
        k: Integer to find the maximum sum.

    Returns:
        int: The maximum sum of increasing subsequence.
    """
    n = len(nums)
    if n == 0:
        return 0
    if k == 0:
        return nums[0]

    # dp[i] will store the maximum sum ending at i
    dp = [0] * (k + 1)
    dp[0] = nums[0]

    for i in range(1, n):
        for j in range(i, k + 1):
            if nums[i] < nums[j]:
                dp[i] = max(dp[i], dp[j] + nums[i])

    return max(dp[k], dp[k - 1])

