def find_literals(pattern, text):
    """Return the start and end indices of the first occurrence of `pattern` in `text`.

    Args:
        pattern: A string to search for.
        text: The string to search within.

    Returns:
        A tuple (start, end) where start is the start index and end is the end index.
        If no such match is found, returns (None, None).
    """
    start = 0
    end = len(text) - 1
    while start <= end:
        mid = (start + end) // 2
        if text[mid] == pattern:
            return (start, mid)
        elif text[mid] < pattern:
            start = mid + 1
        else:
            end = mid - 1
    return (None, None)

