    Returns:
        The n-th power of each number in nums.

    Raises:
        ValueError: If n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1
    if n == 1:
        return 1
    if n % 2 == 0:
        return 1 ** (n - 1)
