def text_match_wordz_middle(text: str) -> bool:
    """Return True if the given text contains 'z', except at the start and end.

    Args:
        text: The input string to check.

    Returns:
        True if the string is 'z', except at the start and end.
    """
    start, end = 0, len(text) - 1
    while start < end:
        if text[start] == 'z':
            start += 1
        elif text[end] == 'z':
            end -= 1
