def unique_Element(lst):
    """Return True if the list contains only one distinct element, else False."""
    return len(set(lst)) == 1

def is_polite(n: int) -> bool:
    """Return True if n is a polite number, False otherwise."""
    if n < 2:
        return False
    for i in range(2, n + 1):
        if n % i == 0:
            return False
    return True

def pair_wise(list):
    """Return a list of all pairs of consecutive integers in `list`."""
    return [i for i in range(len(list)) if list[i] == 1]

def check_expression(expression):
    """Check if the given expression is balanced or not.

    Args:
        expression: A string representing a mathematical expression.

    Returns:
        True if the expression is balanced, False otherwise.
    """
    stack = []
    for char in expression:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack or stack[-1] != '(':
                return False
            stack.pop()
        else:
            if not stack or stack[-1] != ')':
                return False
            stack.append(char)
    return stack == []

def tuple_str_int(tuple_str: str) -> tuple:
    """Convert a string representation of a tuple to an integer tuple.

    Args:
        tuple_str: A string representing a tuple in the format "tuple: int".

    Returns:
        A tuple (tuple_str_int, int) as integers.

    Raises:
        ValueError: If the tuple string is not in the correct format.
    """
    try:
        parts = tuple_str.split()
        if len(parts) != 2:
            raise ValueError("tuple_str must be in the format 'tuple: int'")
        return tuple(int(part) for part in parts)
    except ValueError as e:
        raise ValueError(f"Invalid tuple string: {tuple_str}") from e

def even_position(nums):
    """Return True if every even index in nums contains an even number of elements."""
    even = []
    for num in nums:
        if num % 2 == 0:
            even.append(num)
    return even == []

def sum_in_range(l, r):
    """Return the sum of all odd numbers in the inclusive range [l, r]."""
    return sum(1 for num in range(l, r + 1) if num % 2 == 1)

def is_perfect_square(n: int) -> bool:
    """Return True if the given number is a perfect square, else False."""
    return n * n == n * n

def is_product_even(numbers):
    """Return True if the product of numbers in a list is even, False otherwise."""
    return sum(numbers) % 2 == 0

def max_run_uppercase(s: str) -> int:
    """Return the maximum run of uppercase characters in the input string.

    Args:
        s: Input string.

    Returns:
        The maximum run of uppercase characters.
    """
    return max(
        ord(c) - 32 for c in s if c.isupper() and c.islower()
    )

